package com.example.rootmanager

import android.graphics.Color
import android.os.Bundle
import android.text.method.ScrollingMovementMethod
import android.view.View
import androidx.appcompat.app.AlertDialog
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.example.rootmanager.databinding.ActivityMainBinding
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

class MainActivity : AppCompatActivity() {

    private lateinit var binding: ActivityMainBinding
        private var isRootGranted = false

            override fun onCreate(savedInstanceState: Bundle?) {
                    super.onCreate(savedInstanceState)
                            binding = ActivityMainBinding.inflate(layoutInflater)
                                    setContentView(binding.root)

                                            setupUI()
                                                    checkInitialRootStatus()
                                                        }

                                                            private fun setupUI() {
                                                                    binding.tvActivityLog.movementMethod = ScrollingMovementMethod()
                                                                            binding.tvDeviceInfo.text = RootHelper.getDeviceInfo()

                                                                                    binding.btnRequestRoot.setOnClickListener {
                                                                                                showConsentDialog(
                                                                                                                title = "Konfirmasi Izin Root",
                                                                                                                                message = "Aplikasi akan meminta hak akses Superuser (su) dari pengelola root Anda (seperti Magisk/KernelSU). Lanjutkan?"
                                                                                                                                            ) {
                                                                                                                                                            verifyRootPermission()
                                                                                                                                                                        }
                                                                                                                                                                                }

                                                                                                                                                                                        binding.btnCheckSelinux.setOnClickListener {
                                                                                                                                                                                                    showConsentDialog(
                                                                                                                                                                                                                    title = "Konfirmasi Perintah Sistem",
                                                                                                                                                                                                                                    message = "Jalankan perintah 'getenforce' sebagai root untuk memeriksa status SELinux?"
                                                                                                                                                                                                                                                ) {
                                                                                                                                                                                                                                                                runSafeRootCommand("getenforce", "Status SELinux")
                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                            binding.btnCheckKernel.setOnClickListener {
                                                                                                                                                                                                                                                                                                        showConsentDialog(
                                                                                                                                                                                                                                                                                                                        title = "Konfirmasi Perintah Sistem",
                                                                                                                                                                                                                                                                                                                                        message = "Jalankan perintah 'uname -a' sebagai root untuk membaca informasi kernel?"
                                                                                                                                                                                                                                                                                                                                                    ) {
                                                                                                                                                                                                                                                                                                                                                                    runSafeRootCommand("uname -a", "Informasi Kernel")
                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                binding.btnClearLog.setOnClickListener {
                                                                                                                                                                                                                                                                                                                                                                                                            binding.tvActivityLog.text = ""
                                                                                                                                                                                                                                                                                                                                                                                                                        appendLog("Log aktivitas dibersihkan.")
                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                        /**
                                                                                                                                                                                                                                                                                                                                                                                                                                             * Pengecekan awal pasif tanpa memicu pop-up izin root.
                                                                                                                                                                                                                                                                                                                                                                                                                                                  */
                                                                                                                                                                                                                                                                                                                                                                                                                                                      private fun checkInitialRootStatus() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              appendLog("Memeriksa keberadaan biner su...")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      val suExists = RootHelper.isSuBinaryPresent()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (suExists) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          binding.tvRootStatusTitle.text = "Biner Root Terdeteksi"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      binding.tvRootStatusTitle.setTextColor(Color.parseColor("#D97706")) // Oranye
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  binding.tvRootStatusDesc.text =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "Perangkat memiliki biner su. Tekan tombol di bawah untuk memverifikasi izin akses."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              binding.btnRequestRoot.isEnabled = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          appendLog("Biner su ditemukan pada sistem.")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              binding.tvRootStatusTitle.text = "Perangkat Belum Di-Root"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          binding.tvRootStatusTitle.setTextColor(Color.parseColor("#DC2626")) // Merah
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      binding.tvRootStatusDesc.text =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "Aplikasi ini membutuhkan perangkat yang sudah memiliki akses root untuk menjalankan fitur pengelolaan."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  binding.btnRequestRoot.isEnabled = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              binding.cardActions.visibility = View.GONE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          appendLog("Peringatan: Biner su tidak ditemukan. Perangkat tidak memiliki akses root.")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          /**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               * Meminta izin root secara aktif di background thread.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        private fun verifyRootPermission() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                appendLog("Meminta persetujuan akses root...")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        binding.btnRequestRoot.isEnabled = false

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                lifecycleScope.launch(Dispatchers.IO) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val (granted, message) = RootHelper.requestRootAccess()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        withContext(Dispatchers.Main) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        isRootGranted = granted
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        binding.btnRequestRoot.isEnabled = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        appendLog(message)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (granted) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            binding.tvRootStatusTitle.text = "Akses Root Aktif (Granted)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                binding.tvRootStatusTitle.setTextColor(Color.parseColor("#059669")) // Hijau
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    binding.tvRootStatusDesc.text =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Izin Superuser telah diverifikasi. Anda dapat menggunakan utilitas di bawah."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                binding.btnRequestRoot.text = "Verifikasi Ulang Izin Root"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    binding.cardActions.visibility = View.VISIBLE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        binding.tvRootStatusTitle.text = "Akses Root Ditolak"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            binding.tvRootStatusTitle.setTextColor(Color.parseColor("#DC2626"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                binding.tvRootStatusDesc.text =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Permintaan akses ditolak. Pastikan Anda mengizinkan aplikasi ini di pengelola root."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            binding.cardActions.visibility = View.GONE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        /**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             * Menjalankan perintah root tertentu dan mencatat hasilnya ke log.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      private fun runSafeRootCommand(command: String, label: String) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!isRootGranted) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          appendLog("Gagal: Izin root belum diberikan.")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      appendLog("Menjalankan perintah ($label): $command")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              lifecycleScope.launch(Dispatchers.IO) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          val result = RootHelper.executeRootCommand(command)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      withContext(Dispatchers.Main) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      appendLog("Hasil [$label]: $result")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  /**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       * Dialog wajib sebelum mengeksekusi interaksi tingkat sistem.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                private fun showConsentDialog(title: String, message: String, onConfirm: () -> Unit) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AlertDialog.Builder(this)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .setTitle(title)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .setMessage(message)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .setPositiveButton("Setuju & Lanjutkan") { dialog, _ ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dialog.dismiss()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onConfirm()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .setNegativeButton("Batal") { dialog, _ ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    appendLog("Aksi dibatalkan oleh pengguna.")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    dialog.dismiss()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .show()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private fun appendLog(message: String) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val timestamp = SimpleDateFormat("HH:mm:ss", Locale.getDefault()).format(Date())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    binding.tvActivityLog.append("[$timestamp] $message\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        